import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Naive GEMM kernel: out = x * w^T + b
__global__ void gemm_kernel(const float* __restrict__ x,
                            const float* __restrict__ w,
                            const float* __restrict__ b,
                            float* __restrict__ out,
                            int batch_size, int in_features, int out_features) {
    int row = blockIdx.x;
    int col = threadIdx.x;
    if (row < batch_size && col < out_features) {
        float val = b[col];
        for (int i = 0; i < in_features; i++){
            val += x[row * in_features + i] * w[col * in_features + i];
        }
        out[row * out_features + col] = val;
    }
}

torch::Tensor gemm_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = w.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());
    dim3 grid(batch_size);
    dim3 block(out_features);

    gemm_kernel<<<grid, block>>>(x.data_ptr<float>(),
                                 w.data_ptr<float>(),
                                 b.data_ptr<float>(),
                                 out.data_ptr<float>(),
                                 batch_size, in_features, out_features);

    return out;
}

// Naive GroupNorm + HardTanh kernel
__global__ void groupnorm_hardtanh_kernel(const float* __restrict__ input,
                                          float* __restrict__ output,
                                          const float* __restrict__ gamma,
                                          const float* __restrict__ beta,
                                          int batch_size,
                                          int out_features,
                                          int num_groups,
                                          float eps,
                                          float min_val,
                                          float max_val) {
    int total = batch_size * out_features;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total) {
        int batch_i = idx / out_features;
        int channel_i = idx % out_features;
        int group_size = out_features / num_groups;
        int group_i = channel_i / group_size;
        int group_start = group_i * group_size;

        // Compute mean
        float mean = 0.0f;
        for(int c = 0; c < group_size; c++){
            mean += input[batch_i * out_features + group_start + c];
        }
        mean /= group_size;

        // Compute variance
        float var = 0.0f;
        for(int c = 0; c < group_size; c++){
            float diff = input[batch_i * out_features + group_start + c] - mean;
            var += diff * diff;
        }
        var /= group_size;
        float inv_std = rsqrtf(var + eps);

        float x = input[idx];
        float x_norm = (x - mean) * inv_std;
        float x_gamma = x_norm * gamma[channel_i];
        float x_beta = x_gamma + beta[channel_i];
        float x_clamped = fminf(fmaxf(x_beta, min_val), max_val);

        output[idx] = x_clamped;
    }
}

torch::Tensor groupnorm_hardtanh_cuda(torch::Tensor input,
                                      torch::Tensor gamma,
                                      torch::Tensor beta,
                                      int num_groups,
                                      float min_val,
                                      float max_val,
                                      float eps=1e-5) {
    int batch_size = input.size(0);
    int out_features = input.size(1);

    auto out = torch::zeros_like(input);
    int total = batch_size * out_features;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    groupnorm_hardtanh_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        batch_size,
        out_features,
        num_groups,
        eps,
        min_val,
        max_val
    );

    return out;
}
