cpp_source = r"""
torch::Tensor gemm_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b);
torch::Tensor groupnorm_hardtanh_cuda(torch::Tensor input,
                                      torch::Tensor gamma,
                                      torch::Tensor beta,
                                      int num_groups,
                                      float min_val,
                                      float max_val,
                                      float eps);
"""

custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["gemm_cuda", "groupnorm_hardtanh_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses GEMM, GroupNorm, and HardTanh with custom CUDA kernels.
    """
    def __init__(self, in_features, out_features, num_groups, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.num_groups = num_groups
        self.min_val = hardtanh_min
        self.max_val = hardtanh_max

        # Parameters for GEMM
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

        # Parameters for GroupNorm
        self.gn_gamma = nn.Parameter(torch.ones(out_features))
        self.gn_beta = nn.Parameter(torch.zeros(out_features))

    def forward(self, x):
        # Custom GEMM
        x = custom_ops.gemm_cuda(x, self.weight, self.bias)
        # Custom GroupNorm + HardTanh
        x = custom_ops.groupnorm_hardtanh_cuda(x,
                                               self.gn_gamma,
                                               self.gn_beta,
                                               self.num_groups,
                                               self.min_val,
                                               self.max_val,
                                               1e-5)
        return x
